@dataclass
class Harness:
    tmpdir: str
    store: WalletStore
    service: WalletService

    def share_signature(self, wallet_id: str, share_id: str,
                        signing_request_id: str, message: str) -> str:
        """模拟某一份额持有方：用本地份额私钥对拼接载荷签名，返回 hex。"""
        share = self.store.get_share(wallet_id, share_id)
        payload = crypto.build_payload(signing_request_id, message)
        return crypto.sign_share(
            bytes.fromhex(share["private_key"]), payload
        ).hex()

    def two_signatures(self, wallet_id: str, signing_request_id: str,
                       message: str) -> list[dict]:
        return [
            {
                "share_id": sid,
                "signature": self.share_signature(
                    wallet_id, sid, signing_request_id, message
                ),
            }
            for sid in ("share-1", "share-2")
        ]

    def share_private_hex(self, wallet_id: str, share_id: str) -> str:
        return self.store.get_share(wallet_id, share_id)["private_key"]


def make_harness(tmpdir: str) -> Harness:
    store = WalletStore(tmpdir)
    return Harness(tmpdir=tmpdir, store=store, service=WalletService(store))


@dataclass
class RunningServer:
    harness: Harness
    base_url: str
    logs: list[str]
    _httpd: object

    def stop(self) -> None:
        self._httpd.shutdown()
        self._httpd.server_close()

    def request(self, method: str, path: str, body=None):
        data = None
        headers = {"Accept": "application/json"}
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(
            self.base_url + path, data=data, method=method, headers=headers
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            return exc.code, json.loads(exc.read().decode("utf-8"))


@contextmanager
def http_server(tmpdir: str) -> Iterator[RunningServer]:
    """在后台线程启动真实 HTTP 服务器，端口由内核分配。"""
    harness = make_harness(tmpdir)
    logs: list[str] = []
    httpd = create_server("127.0.0.1", 0, harness.service, trace=logs.append)
    port = httpd.server_address[1]
    thread = threading.Thread(
        target=httpd.serve_forever, kwargs={"poll_interval": 0.02}, daemon=True
    )
    thread.start()
    running = RunningServer(
        harness=harness,
        base_url=f"http://127.0.0.1:{port}",
        logs=logs,
        _httpd=httpd,
    )
    try:
        yield running
    finally:
        running.stop()
        thread.join(timeout=2)

def cancel_sign_request(
    self, wallet_id: str, request_id: str, body: object
) -> tuple[int, dict]:
    """撤销 pending 且未过期的审批单。

    request_cancelled 是唯一提交点；同 rid + cancel_id + reason 重放
    返回 200。cancel_id 复用或参数变化、审批单非 pending、冻结钱包
    均为 409。
    """
    record = None
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            self._get_wallet_or_404(wallet_id)
            self._assert_wallet_active_locked(wallet_id)
            if not isinstance(body, dict) or set(body) != {
                "cancel_id",
                "reason",
            }:
                raise ServiceError(
                    400,
                    "body must contain exactly cancel_id and reason",
                )
            cancel_id = body["cancel_id"]
            reason = body["reason"]
            if not isinstance(cancel_id, str) or not _SAFE_ID.match(
                cancel_id
            ):
                raise ServiceError(400, "invalid cancel_id")
            if not self._valid_request_cancel_reason(reason):
                raise ServiceError(
                    400,
                    "reason must be a non-blank string of 1 to "
                    f"{MAX_REASON_LENGTH} characters",
                )
            record = self._fetch_request_or_404(wallet_id, request_id)
            record = self._expire_if_needed(wallet_id, record)
            cancel_events = self._request_cancel_events_strict(wallet_id)
            existing = cancel_events.get(request_id)
            if existing is not None:
                if (
                    existing["actor_id"] == cancel_id
                    and existing["reason"] == reason
                ):
                    return 200, self._request_view(record)
                raise ServiceError(
                    409,
                    "signing request was cancelled with different parameters",
                )
            for event in cancel_events.values():
                if event["actor_id"] == cancel_id:
                    raise ServiceError(
                        409, "cancel_id has already been used"
                    )
            if record["state"] != "pending":
                raise ServiceError(
                    409,
                    f"signing request {request_id!r} is {record['state']}, "
                    "not pending",
                )
            cancelled = dict(record)
            cancelled["state"] = "cancelled"
            cancelled["reason"] = reason
            self._store.save_request_cancel_intent(
                wallet_id, request_id, cancel_id, reason, record
            )
            self._store.update_request(
                wallet_id, request_id, cancelled
            )
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_REQUEST_CANCELLED,
                        request_id=request_id,
                        actor_id=cancel_id,
                        reason=reason,
                        details={
                            "cancel_id": cancel_id,
                            "reason": reason,
                        },
                    ),
                )
            except BaseException:
                self._store.update_request(
                    wallet_id, request_id, record
                )
                self._store.delete_request_cancel_intent(
                    wallet_id, request_id
                )
                raise
            self._store.delete_request_cancel_intent(
                wallet_id, request_id
            )
            record = cancelled
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._request_view(record)

